'use strict';

// §07 load_data formats, read from the fixtures flatppl-rust tests too
// (`crates/host/tests/fixtures/data`, regenerated by `generate.py` there): both
// engines must read the same values and refuse the same content.

const { test } = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const { processSource } = require('..');
const { makeMatCtx } = require('./_materialise-helpers.ts');
const { readArrow, readSafetensors } = require('../data-formats.ts');

const FIXTURES = path.join(__dirname, 'fixtures', 'data');
const fixture = (name: string) => new Uint8Array(fs.readFileSync(path.join(FIXTURES, name)));

function context(source: string, names: string[], sources: Record<string, string> = {}) {
  const files = Object.fromEntries(names.map(name => [name, fixture(name)]));
  return makeMatCtx(source, { path: 'model.flatppl', bundle: { sources, files } as any, sampleCount: 1 });
}

async function values(ctx: any, name: string): Promise<number[]> {
  const measure = await ctx.getMeasure(name);
  return measure.value?.data ? Array.from(measure.value.data, Number) : [Number(measure.samples[0])];
}

function refusal(source: string, names: string[], sources: Record<string, string> = {}): string {
  const files = Object.fromEntries(names.map(name => [name, fixture(name)]));
  const result = processSource(source, { path: 'model.flatppl', bundle: { sources, files } });
  const error = result.diagnostics.find((d: any) => d.severity === 'error');
  assert.ok(error, `must refuse: ${source}`);
  return error.message;
}

test('every §07 format reads the same table', async () => {
  for (const file of ['events.json', 'events_columns.json', 'events.csv', 'events.wsv', 'events.arrow', 'events.arrows']) {
    const { ctx } = context(`data=load_data("${file}",cartpow(cartprod(a=reals,b=integers,flag=booleans),2))
      a=data.a
      b=data.b
      f=data.flag`, [file]);
    assert.deepEqual(await values(ctx, 'a'), [1.5, -2], file);
    assert.deepEqual(await values(ctx, 'b'), [2, 0], file);
    assert.deepEqual(await values(ctx, 'f'), [1, 0], file);
  }
});

test('a one-column delimited source reads as a vector', async () => {
  const { ctx } = context('x=load_data("column.csv",cartpow(reals,3))', ['column.csv']);
  assert.deepEqual(await values(ctx, 'x'), [0.5, -1, 2.75]);
  assert.match(refusal('x=load_data("events.csv",cartpow(reals,3))', ['events.csv']),
    /exactly one column, and this one has 4/);
});

test('untyped numbers are integers when exactly integral, and true/false read as 1/0', async () => {
  const { ctx } = context(`d=load_data("untyped.csv",cartpow(cartprod(i=integers,flag=reals),3))
    i=d.i
    f=d.flag
    j=load_data("untyped.json",cartprod(i=cartpow(integers,3))).i`, ['untyped.csv', 'untyped.json']);
  assert.deepEqual(await values(ctx, 'i'), [3, 3, 1000]);
  assert.deepEqual(await values(ctx, 'f'), [1, 0, 1]);
  assert.deepEqual(await values(ctx, 'j'), [3, 3, 1000]);
  for (const file of ['untyped.csv', 'untyped.json']) {
    assert.match(refusal(`d=load_data("${file}",cartprod(x=cartpow(integers,3)))\ny=d.x`, [file]),
      /is not an integer/, file);
  }
});

test('delimited cells and tables refuse with the reason', () => {
  for (const [domain, reason] of [
    ['cartprod(a=integers)', /is not an integer/],
    ['cartprod(a=posreals)', /outside/],
    ['cartprod(a=booleans)', /is not a boolean/],
    ['cartprod(missing=reals)', /missing field 'missing'/],
  ] as const) {
    assert.match(refusal(`d=load_data("events.csv",cartpow(${domain},3))\ny=d`, ['events.csv']), reason, domain);
  }
  assert.match(refusal('d=load_data("events.csv",cartpow(cartprod(a=reals),4))\ny=d.a', ['events.csv']),
    /does not match shape/);
  assert.match(refusal('d=load_data("events.csv",cartpow(cartprod(a=cartpow(reals,2)),2))\ny=d.a', ['events.csv']),
    /delimited cell, which holds one scalar/);
  assert.match(refusal('d=load_data("empty.csv",cartpow(cartprod(a=reals,b=reals),2))\ny=d.b', [],
    { 'empty.csv': 'a,b\n1,\n3,4\n' }), /is missing/);
  assert.match(refusal('d=load_data("strings.json",cartprod(b=cartpow(reals,2)))\ny=d.b', [],
    { 'strings.json': '{"a": [1, 2], "b": ["1.5", "2"]}' }), /is not a number/);
  assert.match(refusal('m=load_data("m.json",cartpow(reals,[2,2]))', [],
    { 'm.json': '[[1,2,3],[4,5,6],[7,8,9]]' }), /does not match shape \[2,2\]/);
});

test('Safetensors keys form nested records, and every dtype reads its values', async () => {
  const { ctx } = context(`net=load_data("net.safetensors",cartprod(W=cartpow(reals,[2,3]),b=cartpow(reals,2),count=integers,enc=cartprod(layer=cartprod(weight=cartpow(integers,2),mask=cartpow(booleans,2),half=cartpow(reals,2)))))
    W=net.W
    b=net.b
    count=net.count
    weight=net.enc.layer.weight
    mask=net.enc.layer.mask
    half=net.enc.layer.half`, ['net.safetensors']);
  assert.deepEqual(await values(ctx, 'W'), [1, 2, 3, 4, 5, 6.5]);
  assert.deepEqual(await values(ctx, 'b'), [0.25, -0.5]);
  assert.deepEqual(await values(ctx, 'count'), [5]);
  assert.deepEqual(await values(ctx, 'weight'), [3, -4]);
  assert.deepEqual(await values(ctx, 'mask'), [1, 0]);
  assert.deepEqual(await values(ctx, 'half'), [1.5, -0.125]);

  const fields: Array<[string, string, number[]]> = [
    ['f64', 'reals', [1.5, -2]], ['f32', 'reals', [1.5, -2]], ['f16', 'reals', [1.5, -2]],
    ['bf16', 'reals', [1.5, -3]], ['i64', 'integers', [1, -2]], ['i32', 'integers', [1, -2]],
    ['i16', 'integers', [1, -2]], ['i8', 'integers', [1, -2]], ['u64', 'integers', [1, 2]],
    ['u32', 'integers', [1, 2]], ['u16', 'integers', [1, 2]], ['u8', 'integers', [1, 2]],
    ['bool', 'booleans', [1, 0]],
  ];
  const domain = fields.map(([name, set]) => `${name}=cartpow(${set},2)`).join(',');
  const dtypes = context(`t=load_data("dtypes.safetensors",cartprod(${domain}))\n`
    + fields.map(([name]) => `v_${name}=t.${name}`).join('\n'), ['dtypes.safetensors']);
  for (const [name, , want] of fields) assert.deepEqual(await values(dtypes.ctx, `v_${name}`), want, name);
});

test('Safetensors dtypes, shapes and key rules refuse as in flatppl-rust', () => {
  for (const [domain, reason] of [
    ['cartprod(W=cartpow(integers,[2,3]))', /a real value where the declared set holds integers/],
    ['cartprod(enc=cartprod(layer=cartprod(weight=cartpow(booleans,2))))', /an integer value where the declared set holds booleans/],
    ['cartprod(W=cartpow(reals,[3,2]))', /does not match shape/],
    ['cartprod(W=cartpow(reals,[2,2]))', /does not match shape/],
    ['cartprod(b=cartpow(reals,4))', /does not match shape/],
    ['cartprod(enc=cartprod(other=reals))', /missing field 'other'/],
  ] as const) {
    assert.match(refusal(`net=load_data("net.safetensors",${domain})\ny=net`, ['net.safetensors']), reason, domain);
  }
  for (const [file, reason] of [
    ['empty_segment', 'key `enc..weight` has an empty path segment'],
    ['empty_key', 'key `...` is empty after trimming its dots'],
    ['duplicate_path', 'keys trimming to `enc.weight` name the same record path'],
    ['prefix_and_leaf', '`enc` is both a tensor and a record path prefix'],
    ['fp8', 'dtype F8_E4M3 has no FlatPPL value set'],
    ['u64', 'U64 value 9223372036854775808 exceeds int64'],
  ]) {
    const message = refusal(`net=load_data("${file}.safetensors",cartprod(x=reals))\ny=net`, [`${file}.safetensors`]);
    assert.ok(message.includes(reason), `${file}: ${message}`);
  }
});

test('Arrow typed columns read past every other layout, from the file and the stream', async () => {
  const columns: Array<[string, string, number[]]> = [
    ['i8', 'integers', [1, -2, 1, -2]], ['i16', 'integers', [1, -2, 1, -2]],
    ['i32', 'integers', [1, -2, 1, -2]], ['i64', 'integers', [1, -2, 1, -2]],
    ['u8', 'integers', [1, 2, 1, 2]], ['u16', 'integers', [1, 2, 1, 2]],
    ['u32', 'integers', [1, 2, 1, 2]], ['u64', 'integers', [1, 2, 1, 2]],
    ['f16', 'reals', [1.5, -2, 1.5, -2]], ['f32', 'reals', [1.5, -2, 1.5, -2]],
    ['bool', 'booleans', [1, 0, 1, 0]],
  ];
  for (const file of ['types.arrow', 'types.arrows']) {
    const domain = columns.map(([name, set]) => `${name}=${set}`).join(',');
    const { ctx } = context(`t=load_data("${file}",cartpow(cartprod(${domain}),4))\n`
      + columns.map(([name]) => `v_${name}=t.${name}`).join('\n'), [file]);
    for (const [name, , want] of columns) assert.deepEqual(await values(ctx, `v_${name}`), want, `${file} ${name}`);
    for (const [column, reason] of [
      ['f64', /is missing/], ['null', /is missing/],
      ['utf8', /holds Arrow strings/], ['large_utf8', /holds Arrow strings/],
      ['view', /holds Arrow strings/], ['dict', /holds Arrow strings/],
      ['binary', /unsupported Arrow type/], ['list', /unsupported Arrow type/],
      ['large_list', /unsupported Arrow type/], ['list_view', /unsupported Arrow type/],
      ['fixed_list', /unsupported Arrow type/], ['struct', /unsupported Arrow type/],
      ['sparse', /unsupported Arrow type/], ['dense', /unsupported Arrow type/],
      ['ree', /unsupported Arrow type/], ['time', /unsupported Arrow type/],
    ] as const) {
      assert.match(refusal(`t=load_data("${file}",cartpow(cartprod(${column}=reals),4))\ny=t.${column}`, [file]),
        reason, `${file} ${column}`);
    }
  }
  assert.match(refusal('t=load_data("compressed.arrow",cartpow(cartprod(f64=reals),4))\ny=t.f64', ['compressed.arrow']),
    /Arrow IPC: compressed record batches are not read/);
  assert.match(refusal('t=load_data("u64.arrow",cartpow(cartprod(x=integers),1))\ny=t.x', ['u64.arrow']),
    /outside int64/);
  const { ctx } = context('a=load_data("mixed.arrow",cartpow(cartprod(a=reals),2)).a', ['mixed.arrow']);
  assert.deepEqual(await values(ctx, 'a'), [1.5, 2.5]);
});

test('malformed binary sources refuse', () => {
  assert.throws(() => readArrow(new Uint8Array([0xff, 0xff, 0xff, 0xff, 0, 0, 0, 0])), /Arrow IPC: no schema/);
  assert.throws(() => readArrow(new TextEncoder().encode('ARROW1\0\0short')), /footer and magic/);
  for (const bytes of [new Uint8Array(4), new Uint8Array([255, 0, 0, 0, 0, 0, 0, 0])]) {
    assert.throws(() => readSafetensors(bytes), /Safetensors: (missing the header length|header length exceeds the file)/);
  }
  const header = (text: string) => {
    const json = new TextEncoder().encode(text);
    const out = new Uint8Array(8 + json.length + 8);
    new DataView(out.buffer).setBigUint64(0, BigInt(json.length), true);
    out.set(json, 8);
    return out;
  };
  for (const [text, reason] of [
    ['[1]', /expected a JSON object/],
    ['{not json', /header:/],
    ['{"x": {"dtype": "F64"}}', /expects a dtype, a shape and two data offsets/],
    ['{"x": {"dtype": "F64", "shape": [1], "data_offsets": [0, 16]}}', /outside the data buffer/],
    ['{"x": {"dtype": "F64", "shape": [2], "data_offsets": [0, 8]}}', /8 bytes hold 1 F64 values, but the shape \[2\] needs 2/],
    ['{"x": {"dtype": "BOOL", "shape": [1], "data_offsets": [0, 1]}}', null],
  ] as const) {
    if (reason) assert.throws(() => readSafetensors(header(text)), reason, text);
  }
  const bool = header('{"x": {"dtype": "BOOL", "shape": [1], "data_offsets": [0, 1]}}');
  bool[bool.length - 8] = 2;
  assert.throws(() => readSafetensors(bool), /BOOL byte 2 is neither 0 nor 1/);
});

test('an unknown extension refuses at the call, before any read', () => {
  const result = processSource('x=1.0\ndata=load_data("events.parquet",cartpow(reals,2))', { path: 'model.flatppl', bundle: { sources: {} } });
  const error = result.diagnostics.find((d: any) => d.severity === 'error');
  assert.match(error.message, /unsupported file extension `\.parquet`/);
  // Engine locations count lines from zero: this is the `data` binding.
  assert.deepEqual([error.binding, error.loc.start.line, error.loc.start.col], ['data', 1, 5]);
});
